-- =============================================================================
-- Studuel — Migration 228 : ENSEIGNEMENT SCIENTIFIQUE Tle — LE PROGRAMME OFFICIEL
--
-- ⚠️ FICHIER GÉNÉRÉ — ne pas éditer à la main.
--    Source : scripts/contenu/*.mjs
--    Regénérer : node scripts/seed-contenu.mjs --num 228 --slugs enseignement-scientifique
--
-- CONSTAT MESURÉ (sonde en lecture seule sur la base, 05/08/2026) :
-- l'enseignement scientifique de Terminale n'avait que 4 chapitres, taillés
-- dans un découpage maison (« L'atmosphère et le climat », « L'énergie :
-- conversions et enjeux », « Une histoire du vivant », « L'intelligence
-- artificielle ») qui résumait TOUT le programme en quatre fiches. Un élève qui
-- révisait le transport de l'électricité, les modèles démographiques, les
-- cycles de Milankovitch ou l'histoire de la lignée humaine ne trouvait rien.
-- Cette migration installe les 16 fiches du programme officiel, dans l'ordre
-- des 6 chapitres du BO, et retire les 4 fiches de synthèse qu'elles
-- recouvrent entièrement.
--
-- Cette migration apporte : 16 chapitres, 16 leçons,
-- 16 quiz et 128 questions, sur 1 matière.
--
-- CHOIX ASSUMÉS :
--  · tous les quiz sont `is_free = true`. Aucun compte ne peut aujourd’hui
--    passer `tier1` (aucun paiement n’existe), donc un quiz payant serait un
--    quiz INVISIBLE pour 100 % des élèves — le contraire du but ;
--  · chaque cours porte des sections `##`, ce qui rend sa carte mentale
--    dérivable (cf. lib/mind-map-auto) : aucune tuile ne promet dans le vide.
--
-- Idempotent : les UUID sont dérivés du contenu (SHA-1), donc stables ; les
-- INSERT sont tous gardés par ON CONFLICT DO NOTHING. Rejouable sans risque.
--
-- PRÉREQUIS : 002, 008, 191, 193 exécutées (les matières doivent exister).
-- À exécuter dans : Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

-- 0. Ménage ----------------------------------------------------------------
-- [enseignement-scientifique] La file « À revoir » d'abord : review_items.item_id n'a PAS de clé
-- [enseignement-scientifique] étrangère (il pointe soit une question, soit une carte). Rien ne casse si on
-- [enseignement-scientifique] l'oublie — le lecteur écarte déjà un contenu disparu — mais le compteur
-- [enseignement-scientifique] « X à revoir » continuerait de compter des questions qui n'existent plus.
DELETE FROM public.review_items ri
 USING public.quiz_questions qq, public.quizzes qz, public.lessons l,
       public.chapters c, public.subjects s
 WHERE ri.item_kind = 'question'
   AND ri.item_id = qq.id
   AND qq.quiz_id = qz.id
   AND qz.lesson_id = l.id
   AND l.chapter_id = c.id
   AND c.subject_id = s.id
   AND s.slug = 'enseignement-scientifique'
   AND c.level = 'Tle'
   AND l.title IN ('L''essentiel du cours', 'Exercices types');

-- [enseignement-scientifique] Les quiz ensuite : quizzes.lesson_id est ON DELETE SET NULL, donc
-- [enseignement-scientifique] supprimer le chapitre laisserait derrière lui des quiz orphelins, rattachés à
-- [enseignement-scientifique] aucune leçon mais toujours servis par le moteur de révision.
DELETE FROM public.quizzes q
 USING public.lessons l, public.chapters c, public.subjects s
 WHERE q.lesson_id = l.id
   AND l.chapter_id = c.id
   AND c.subject_id = s.id
   AND s.slug = 'enseignement-scientifique'
   AND c.level = 'Tle'
   AND l.title IN ('L''essentiel du cours', 'Exercices types');

-- [enseignement-scientifique] Puis les chapitres : leçons, fiches de révision, supports, progression
-- [enseignement-scientifique] et chapitres cochés partent en cascade (toutes les clés étrangères vers
-- [enseignement-scientifique] chapters et lessons sont ON DELETE CASCADE).
DELETE FROM public.chapters c
 USING public.subjects s
 WHERE c.subject_id = s.id
   AND s.slug = 'enseignement-scientifique'
   AND c.level = 'Tle'
   AND EXISTS (
     SELECT 1 FROM public.lessons l
      WHERE l.chapter_id = c.id
        AND l.title IN ('L''essentiel du cours', 'Exercices types')
   );

-- 1. Chapitres -------------------------------------------------------------
